/**
 * One compile inside the plane's compiler: the uploaded workspace files (agents-root relative, base64), the targets, the switches. The plane owns everything else: sessions, judgments, gates, packages, the ship.
 */
export type CompileRequest = {
    /**
     * The wire protocol major, 0.
     */
    protocol: number;
    op: 'compile.run';
    compileId: string;
    targets: Array<string>;
    /**
     * Agents-root-relative path to base64 content.
     */
    files: {
        [key: string]: string;
    };
    coder?: 'claude-code' | 'codex';
    runtimeHarness?: 'claude-code' | 'codex' | 'openai';
    /**
     * Run the live tester on the plane after the compile; it means something on a deploy, since a verified package needs a live run and a compile alone never verifies.
     */
    verify?: boolean;
    /**
     * Skip the compatibility judgment and the anchor: the session writes a new contract from the specification, and the dependents whose pinned contract breaks recompile in the same run.
     */
    newContract?: boolean;
    cascade?: boolean;
    /**
     * Ignore the compile cache for every agent of this compile.
     */
    recompile?: boolean;
    /**
     * Stop after the change step of every target and answer the plans: nothing is written, verified or shipped.
     */
    planOnly?: boolean;
    /**
     * Fix rounds a failing test run may take; zero fails fast.
     */
    maxLiveCycles?: number;
    /**
     * A given contract per agent id, as declaration text: preserved as it is, no judgment asked, a session that drifts from it fails.
     */
    contracts?: {
        [key: string]: string;
    };
    /**
     * Reviewed coder sources per target agent (workspace `src/` relative path to base64 content), written as if a session wrote them: no session opens for a seeded agent, its tests are off and the cache is skipped, and a gate failure fails it with the gate's words. `coder` names the vendor that wrote the source, carried into the artifact's provenance. Every seeded agent's artifact is packed into the plane store and named in its report, modules included, its layer linking the platform libraries at the release's shared location; a seeded agent is never answered as a fleet row.
     */
    seeds?: {
        [key: string]: {
            files: {
                [key: string]: string;
            };
            coder?: {
                name: string;
                cli?: string;
                model?: string;
                effort?: string;
            };
        };
    };
    /**
     * The workspace's own package per agent id: the sha256 digest of the .cern file beside its spec, already in the plane store.
     */
    packages?: {
        [key: string]: string;
    };
};

