export type LsRow = {
    agentId: string;
    type: 'task' | 'job' | 'service' | 'worker' | 'module' | 'interface';
    status: string;
    copies: number;
    ready: string;
    restarts: number;
    cpuMillicores?: number;
    memoryMi?: number;
    journalEntries?: number;
    /**
     * The parked image the plane holds of the agent, what a restart loads, in exact mebibytes (the bytes over 1048576), summed over its generation copies; absent when the plane holds none or the holdings could not be read.
     */
    snapshotMi?: number;
    /**
     * What the plane journaled for the agent since its image, what a restart replays, in exact mebibytes; absent when the holdings could not be read.
     */
    journalMi?: number;
    /**
     * Observed logical incoming starts since totalsSince, independent of trace retention. Replay is deduplicated.
     */
    incomingTotal?: number;
    /**
     * Observed child call starts since totalsSince. New job attempts can create new child calls.
     */
    outgoingTotal?: number;
    /**
     * The calls made of the agent that it holds now and has not answered, summed over the copies that answered when the listing asked them. For a module, the calls into it in flight inside the copies it is linked into; for an interface, the sum over its implementors' rows.
     */
    incomingActive?: number;
    /**
     * The calls the agent's code made and still waits on, summed the same way.
     */
    outgoingActive?: number;
    /**
     * How many running copies the listing asked for the agent's active calls: its own copies; for a module, the copies it is linked into; for an interface, the sum over its implementors' rows.
     */
    copiesAsked?: number;
    /**
     * How many of them answered in time. Fewer than copiesAsked leaves the two sums partial; none of some leaves them unknown.
     */
    copiesAnswered?: number;
    totalsSince?: string;
    inputTokens?: number;
    outputTokens?: number;
    /**
     * Provider-reported USD during the usage window, attributed once to the work owner. Omitted when any turn has no price.
     */
    costUsd?: number;
    functions?: Array<LsFunction>;
};

