/**
 * How many recent records to deliver first (0 without one, capped at 1000).
 */
export type Backlog = number;

/**
 * The moment the stream's reads start from: records at or after it, until one is seen (a deploy passes its own start, so the agent's earlier history is never read).
 */
export type Since = string;

